// Mode: Run Once for All Items

const rows = $input.all().map(item => item.json);

const completed = rows.filter(
  row => String(row.Status ?? '').toLowerCase() === 'completed'
);

if (completed.length === 0) {
  throw new Error(
    'No Completed GulfFix jobs were found. Check the file and Status column.'
  );
}

const number = value => Number(value ?? 0) || 0;

const truthy = value =>
  ['true', '1', 'yes', 'y'].includes(String(value).toLowerCase());

const pct = value => Number((value * 100).toFixed(1));

const average = (items, field) =>
  items.length
    ? items.reduce((sum, row) => sum + number(row[field]), 0) / items.length
    : 0;

const money = value => Number(value.toFixed(0));

const target = 90;

const overallSla =
  completed.filter(row => truthy(row.SLA_Met)).length /
  completed.length;

const overall = {
  jobs: completed.length,
  revenue_aed: money(
    completed.reduce((sum, row) => sum + number(row.RevenueAED), 0)
  ),
  sla_pct: pct(overallSla),
  sla_gap_points: Number(
    (target - pct(overallSla)).toFixed(1)
  ),
  csat: Number(average(completed, 'CSAT').toFixed(2)),
  repeat_visit_pct: pct(
    completed.filter(row => truthy(row.RepeatVisit)).length /
    completed.length
  ),
};

const groupBy = field => {
  const groups = new Map();

  for (const row of completed) {
    const key = row[field] || 'Unknown';

    if (!groups.has(key)) {
      groups.set(key, []);
    }

    groups.get(key).push(row);
  }

  return [...groups.entries()].map(([name, items]) => {
    const sla =
      items.filter(row => truthy(row.SLA_Met)).length /
      items.length;

    return {
      [field === 'Branch' ? 'location' : 'service_type']: name,
      jobs: items.length,
      revenue_aed: money(
        items.reduce(
          (sum, row) => sum + number(row.RevenueAED),
          0
        )
      ),
      revenue_per_job_aed: Number(
        average(items, 'RevenueAED').toFixed(2)
      ),
      sla_pct: pct(sla),
      sla_gap_points: Number(
        (target - pct(sla)).toFixed(1)
      ),
      csat: Number(
        average(items, 'CSAT').toFixed(2)
      ),
      repeat_visit_pct: pct(
        items.filter(row => truthy(row.RepeatVisit)).length /
        items.length
      ),
    };
  });
};

const locations = groupBy('Branch')
  .sort((a, b) => a.sla_pct - b.sla_pct);

const services = groupBy('ServiceType');

const priority = locations[0];

const highestRepeatService = [...services]
  .sort((a, b) => b.repeat_visit_pct - a.repeat_visit_pct)[0];

const highestRevenueService = [...services]
  .sort((a, b) => b.revenue_per_job_aed - a.revenue_per_job_aed)[0];

const lowestRepeatService =
  [...services].sort(
    (a, b) => a.repeat_visit_pct - b.repeat_visit_pct
  )[0];

const bestLocation = locations[locations.length - 1];

const locationDifference = Number(
  (bestLocation.sla_pct - priority.sla_pct).toFixed(1)
);

const repeatDifference = Number(
  (
    highestRepeatService.repeat_visit_pct -
    lowestRepeatService.repeat_visit_pct
  ).toFixed(1)
);

const management_summary = [
  `GulfFix completed ${overall.jobs.toLocaleString()} jobs and generated AED ${overall.revenue_aed.toLocaleString()} revenue.`,
  `Overall SLA is ${overall.sla_pct}% against a ${target}% target (${overall.sla_gap_points} points below target).`,
  `Priority location: ${priority.location} at ${priority.sla_pct}% SLA (${priority.sla_gap_points} points below target).`,
  `Highest repeat-visit service: ${highestRepeatService.service_type} at ${highestRepeatService.repeat_visit_pct}%.`,
  `Highest revenue per job: ${highestRevenueService.service_type} at AED ${highestRevenueService.revenue_per_job_aed}.`,
].join('\n');

const analysis_prompt = `Act as a practical operations manager and report formatter.

Use ONLY the approved facts below. Do not calculate new figures and do not introduce any other location, service, average, or percentage.

Write a concise report with exactly these headings:

1. Main issue
2. Priority location and SLA gap
3. Two data-supported patterns
4. Three practical actions
5. One limitation

Approved facts to copy exactly:

- Priority: ${priority.location}, SLA ${priority.sla_pct}%, ${priority.sla_gap_points} points below the ${target}% target.
- Best location: ${bestLocation.location}, SLA ${bestLocation.sla_pct}%.
- Difference between best and priority location: ${locationDifference} SLA points.
- Highest repeat visits: ${highestRepeatService.service_type}, ${highestRepeatService.repeat_visit_pct}%.
- Lowest repeat visits: ${lowestRepeatService.service_type}, ${lowestRepeatService.repeat_visit_pct}%.
- Difference between highest and lowest repeat visits: ${repeatDifference} percentage points.
- Highest revenue per job: ${highestRevenueService.service_type}, AED ${highestRevenueService.revenue_per_job_aed}.

Use these exact actions:

- Review Dubai's completed-job workflow and compare it with the best-performing location.
- Monitor Dubai SLA weekly against the ${target}% target.
- Investigate the repeat-visit process for ${highestRepeatService.service_type}.

Rules:

- Do not invent causes, trends, averages, or metrics.
- Do not infer customer satisfaction or technician skill.
- Do not mention figures not listed above.
- Copy the approved actions exactly.
- State that this is synthetic portfolio data in the limitation section.
- Keep the report under 220 words.
- Finish every section.`;

const requestBody = {
  model: 'llama-3.2-3b-instruct',
  messages: [
    {
      role: 'user',
      content: analysis_prompt,
    },
  ],
  temperature: 0.1,
  max_tokens: 360,
  stream: false,
};

return [
  {
    json: {
      source: 'GulfFix Home Services — synthetic portfolio dataset',
      period: '2026-01-01 to 2026-06-30',
      target_sla_pct: target,
      overall,
      locations,
      services,
      priority,
      management_summary,
      analysis_prompt,
      requestBody,
    },
  },
];

// n8n Code node
// Mode: Run Once for Each Item
// Place after the LM Studio HTTP Request node.

const rawReport = $json.choices?.[0]?.message?.content || '';
const sourceData = $('Aggregate GulfFix KPIs').first().json;
const priority = sourceData.priority || {};
const overall = sourceData.overall || {};

const cleanText = value => String(value ?? '')
  .replace(/\\n/g, '\n')
  .replace(/\\r/g, '')
  .trim();

return {
  json: {
    report_title: 'GulfFix Operations Improvement Report',
    source: sourceData.source,
    period: sourceData.period,
    completed_jobs: overall.jobs,
    total_revenue_aed: overall.revenue_aed,
    overall_sla_pct: overall.sla_pct,
    overall_sla_gap_points: overall.sla_gap_points,
    average_csat: overall.csat,
    repeat_visit_pct: overall.repeat_visit_pct,
    priority_location: priority.location,
    priority_sla_pct: priority.sla_pct,
    priority_sla_gap_points: priority.sla_gap_points,
    management_summary: cleanText(sourceData.management_summary),
    ai_management_report: cleanText(rawReport),
  },
};
